function dump(n, depth=0){
  if(depth>3) return null;
  const o = {id:n.id, name:n.name, type:n.type, w:n.width, h:n.height};
  if('fills' in n) o.fills = JSON.stringify(n.fills);
  if('cornerRadius' in n) o.radius = n.cornerRadius;
  if(n.type==='TEXT'){ o.characters=n.characters; o.font=n.fontName; o.size=n.fontSize; o.color=JSON.stringify(n.fills); }
  if('children' in n) o.children = n.children.map(c=>dump(c, depth+1));
  return o;
}
return JSON.stringify({button: dump(btn), textfield: dump(tf), statusbar: {id:sb.id,w:sb.width,h:sb.height, type:sb.type}, homeind: {id:hi.id,w:hi.width,h:hi.height, type:hi.type}}, null, 1);

