for(const id of frames){
  const f=await figma.getNodeByIdAsync(id);
  for(const t of f.findAll(n=>n.type==='TEXT'&&targets.includes(n.characters))){
    // find sibling price (right-aligned bold) near this change text
    const p=t.parent.children.find(n=>n.type==='TEXT'&&Math.abs(n.y-t.y)<4&&n.x>t.x&&n.fontSize>=12);
    if(p){await figma.loadFontAsync(t.fontName);t.x=p.x-6-t.width;}
  }
}
